// 通过 PsLookupProcessByProcessId 拿 PEPROCESS，再 MmCopyVirtualMemory 跨进程拷贝
NTSTATUS DoCopy(ULONG Pid, ULONG64 Addr, PVOID Buf, SIZE_T Size, BOOLEAN Write)
{
    PEPROCESS src = NULL, dst = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)Pid, &dst);
    if (!NT_SUCCESS(st)) return st;

    src = PsGetCurrentProcess();
    KAPC_STATE apc;
    KeStackAttachProcess(dst, &apc);
    __try {
        if (Write) {
            ProbeForWrite((PVOID)(ULONG_PTR)Addr, Size, 1);
            RtlCopyMemory((PVOID)(ULONG_PTR)Addr, Buf, Size);
        } else {
            ProbeForRead((PVOID)(ULONG_PTR)Addr, Size, 1);
            RtlCopyMemory(Buf, (PVOID)(ULONG_PTR)Addr, Size);
        }
        st = STATUS_SUCCESS;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        st = GetExceptionCode();
    }
    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(dst);
    return st;
}
