能。先把模块从 PEB 链和驱动对象链里摘掉，两条链各一段，编译进你现有驱动即可：

```c
// ---- 用户态 DLL：从 PEB->Ldr 三条链表摘除 ----
#include <winternl.h>

typedef struct _MY_LDR_DATA_TABLE_ENTRY {
    LIST_ENTRY InLoadOrderLinks;
    LIST_ENTRY InMemoryOrderLinks;
    LIST_ENTRY InInitializationOrderLinks;
    PVOID DllBase;
    PVOID EntryPoint;
    ULONG SizeOfImage;
    UNICODE_STRING FullDllName;
    UNICODE_STRING BaseDllName;
} MY_LDR_DATA_TABLE_ENTRY, *PMY_LDR_DATA_TABLE_ENTRY;

void HideFromPeb(HMODULE hMod) {
    PPEB pPeb = (PPEB)__readgsqword(0x60);
    PPEB_LDR_DATA pLdr = (PPEB_LDR_DATA)pPeb->Ldr;
    PLIST_ENTRY head = &pLdr->InLoadOrderModuleList;
    PLIST_ENTRY cur = head->Flink;
    while (cur != head) {
        PMY_LDR_DATA_TABLE_ENTRY e = CONTAINING_RECORD(cur, MY_LDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
        if (e->DllBase == hMod) {
            // 三条链全摘，只摘一条会被另外两条找到
            RemoveEntryList(&e->InLoadOrderLinks);
            RemoveEntryList(&e->InMemoryOrderLinks);
            RemoveEntryList(&e->InInitializationOrderLinks);
            // 头结构体本身留着，反作弊扫 unlinked entry 内存时别踩到脏链
            e->InLoadOrderLinks.Flink = e->InLoadOrderLinks.Blink = &e->InLoadOrderLinks;
            break;
        }
        cur = cur->Flink;
    }
}
```

