// usage: frida -U -f [包名] -l coin_scan.js
const TARGET = 12345; // 界面上看到的金币数

function scan(mod, patternBytes, min, max) {
  const ranges = Process.enumerateRanges('rw-');
  let hits = 0;
  for (const r of ranges) {
    try {
      const res = Memory.scanSync(r.base, r.size, patternBytes);
      for (const m of res.slice(0, 500)) {
        const v = m.address.readS32();
        if (v >= min && v <= max) {
          console.log('[hit] ' + m.address + ' = ' + v);
          hits++;
        }
      }
    } catch (e) {}
  }
  console.log('total hits: ' + hits);
}

Java.perform(function () {
  setTimeout(function () {
    const hex = ('00000000' + TARGET.toString(16)).slice(-8);
    const pat = hex.match(/../g).reverse().join(' '); // little-endian
    console.log('scan pattern: ' + pat);
    scan(null, pat, 0, 0x7fffffff);
  }, 3000);
});
