## 一、整体结构

驱动端负责读写目标进程的内存，用户端通过 `DeviceIoControl` 下发请求。读写流程使用 `MmCopyVirtualMemory`，该函数由系统签名，因此不触碰目标进程的 PPL 保护，也不触发 `ObRegisterCallbacks` 对句柄权限的检查。用户侧进程不需要 `OpenProcess` 权限，也就不需要在用户态拿 `PROCESS_VM_READ`。

## 二、驱动端

```c
// drv_readwrite.c
#include <ntifs.h>

#define DEVICE_NAME     L"\\Device\\RwDrv"
#define SYMLINK_NAME    L"\\??\\RwDrv"
#define IOCTL_READ      CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE     CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_GETBASE   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQ {
    ULONG  Pid;
    ULONG64 Address;
    ULONG64 Buffer;      // 用户态缓冲区
    ULONG  Size;
    ULONG64 ModuleBase;  // 返回用
} RW_REQ, *PRW_REQ;

static NTSTATUS RwDispatch(PDEVICE_OBJECT dev, PIRP irp) {
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(irp);
    NTSTATUS status = STATUS_INVALID_DEVICE_REQUEST;
    PVOID buf = irp->AssociatedIrp.SystemBuffer;
    ULONG code = sp->Parameters.DeviceIoControl.IoControlCode;
    ULONG outLen = 0;

    if (code == IOCTL_READ || code == IOCTL_WRITE) {
        PRW_REQ req = (PRW_REQ)buf;
        PEPROCESS proc = NULL;
        if (NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc))) {
            SIZE_T done = 0;
            if (code == IOCTL_READ) {
                status = MmCopyVirtualMemory(proc, (PVOID)req->Address,
                                             PsGetCurrentProcess(), (PVOID)req->Buffer,
                                             req->Size, KernelMode, &done);
            } else {
                status = MmCopyVirtualMemory(PsGetCurrentProcess(), (PVOID)req->Buffer,
                                             proc, (PVOID)req->Address,
                                             req->Size, KernelMode, &done);
            }
            ObDereferenceObject(proc);
            outLen = req->Size;
        } else status = STATUS_INVALID_PARAMETER;
    } else if (code == IOCTL_GETBASE) {
        // 遍历目标进程模块基址，返回主模块 base
        PRW_REQ req = (PRW_REQ)buf;
        PEPROCESS proc = NULL;
        if (NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc))) {
            ULONG64 base = 0;
            KAPC_STATE apc;
            KeStackAttachProcess(proc, &apc);
            PVOID modBase = NULL; SIZE_T modSize = 0;
            NTSTATUS s = ZwQueryVirtualMemory(NtCurrentProcess(), 0, MemoryBasicInformation,
                                              (PVOID)&modBase, sizeof(modBase), &modSize);
            // 实际下发时遍历 PEB->Ldr 拿模块；这里示意
            base = (ULONG64)modBase;
            KeUnstackDetachProcess(&apc);
            req->ModuleBase = base;
            ObDereferenceObject(proc);
            status = STATUS_SUCCESS;
            outLen = sizeof(RW_REQ);
        }
    }
    irp->IoStatus.Status = status;
    irp->IoStatus.Information = outLen;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return status;
}

