```cpp
// matrix.h  —— 行主序 4x4，与 D3D/Math 常见布局一致
struct Matrix4x4 {
    float m[4][4];
};

// 世界坐标 -> 屏幕坐标。返回 false 表示在摄像机背后或屏幕外
inline bool WorldToScreen(const float world[3], const Matrix4x4& vm,
                          float screenW, float screenH, float out[2])
{
    // 齐次坐标变换（行主序：行向量 × 矩阵）
    float x = world[0]*vm.m[0][0] + world[1]*vm.m[1][0] + world[2]*vm.m[2][0] + vm.m[3][0];
    float y = world[0]*vm.m[0][1] + world[1]*vm.m[1][1] + world[2]*vm.m[2][1] + vm.m[3][1];
    float z = world[0]*vm.m[0][2] + world[1]*vm.m[1][2] + world[2]*vm.m[2][2] + vm.m[3][2];
    float w = world[0]*vm.m[0][3] + world[1]*vm.m[1][3] + world[2]*vm.m[2][3] + vm.m[3][3];

    if (w < 0.001f) return false;   // 在摄像机背后

    float invW = 1.0f / w;
    float ndcX = x * invW;
    float ndcY = y * invW;

    out[0] = (screenW * 0.5f) * (1.0f + ndcX);
    out[1] = (screenH * 0.5f) * (1.0f - ndcY);   // D3D 屏幕 Y 轴向下
    return (out[0] >= 0 && out[0] <= screenW && out[1] >= 0 && out[1] <= screenH);
}
```

