typedef struct _CR3RW_REQUEST {
    ULONG  ProcessId;       // 目标进程 PID
    ULONG64 Address;        // 目标进程虚拟地址
    ULONG64 Buffer;         // 用户态缓冲区（读=输出，写=输入）
