__forceinline ULONG64 Cr3SwitchAndRun(ULONG64 TargetCr3, void (*fn)(void*), void* ctx)
{
    ULONG64 oldCr3;
    KIRQL   irql;
    _disable();
    irql   = KeRaiseIrqlToDpcLevel();
    oldCr3 = __readcr3();
    __writecr3(TargetCr3);
    fn(ctx);
    __writecr3(oldCr3);
    KeLowerIrql(irql);
    _enable();
    return oldCr3;
}

// 从 PsGetCurrentProcess 链到目标 EPROCESS，读 DTB
ULONG64 GetTargetDtBase(ULONG ProcessId)
{
    PEPROCESS proc = NULL;
    if (NT_SUCCESS(PsLookupProcessByProcessId(ULongToHandle(ProcessId), &proc))) {
        ULONG64 dtb = *(ULONG64*)((PUCHAR)proc + EPROCESS_DTB_OFFSET);
        ObDereferenceObject(proc);
        return dtb;
    }
    return 0;
}
