## 2. CR3 切换 + 物理读写核心

```c
#include <ntifs.h>

// 保存原始 CR3，切换到目标进程物理地址空间
typedef struct _CR3_CONTEXT {
    UINT64 OriginalCr3;
    UINT64 TargetCr3;
    KIRQL  OldIrql;
} CR3_CONTEXT;

// 物理地址 -> 当前 CR3 下的虚拟地址（用 MmMapIoSpace 映射物理页）
PVOID MapPhysical(UINT64 PhysAddr, SIZE_T Size) {
    PHYSICAL_ADDRESS pa;
    pa.QuadPart = PhysAddr & ~0xFFFULL;            // 页对齐
    SIZE_T mapSize = Size + (PhysAddr & 0xFFF);
    PVOID va = MmMapIoSpace(pa, PAGE_ALIGN(mapSize), MmNonCached);
    if (!va) return NULL;
    return (PVOID)((PUCHAR)va + (PhysAddr & 0xFFF));
}

VOID UnmapPhysical(PVOID MappedVa, UINT64 PhysAddr, SIZE_T Size) {
    PVOID base = (PVOID)((PUCHAR)MappedVa - (PhysAddr & 0xFFF));
    MmUnmapIoSpace(base, PAGE_ALIGN(Size + (PhysAddr & 0xFFF)));
}

// 读目标进程虚拟地址：先切 CR3，再走页表翻译
BOOLEAN ReadProcessMemoryCr3(UINT64 TargetCr3, UINT64 VirtualAddr, PVOID Buffer, SIZE_T Size) {
    CR3_CONTEXT ctx;
    ctx.OriginalCr3 = __readcr3();
    ctx.OldIrql = KeRaiseIrqlToDpcLevel();   // 关中断，防止切 CR3 期间被调度
    __writecr3(TargetCr3);

    BOOLEAN ok = TRUE;
    PUCHAR dst = (PUCHAR)Buffer;
    SIZE_T remaining = Size;
    UINT64 va = VirtualAddr;

    while (remaining > 0) {
        // 手动走四级页表翻译出物理地址
        UINT64 phys = 0;
        if (!TranslateVaToPa(va, &phys)) { ok = FALSE; break; }

        SIZE_T pageOffset = va & 0xFFF;
        SIZE_T chunk = min(0x1000 - pageOffset, remaining);

        PVOID mapped = MapPhysical(phys, chunk);
        if (!mapped) { ok = FALSE; break; }

        RtlCopyMemory(dst, mapped, chunk);
        UnmapPhysical(mapped, phys, chunk);

        dst += chunk; va += chunk; remaining -= chunk;
    }

    __writecr3(ctx.OriginalCr3);
    KeLowerIrql(ctx.OldIrql);
    return ok;
}
```

