HANDLE g_port = INVALID_HANDLE_VALUE;

bool km_open(const char* com, int baud = 115200) {
    char path[64];
    sprintf_s(path, "\\\\.\\%s", com);                 // 支持 COM10+
    g_port = CreateFileA(path, GENERIC_READ | GENERIC_WRITE,
                         0, nullptr, OPEN_EXISTING, 0, nullptr);
    if (g_port == INVALID_HANDLE_VALUE) return false;

    DCB dcb{}; dcb.DCBlength = sizeof(dcb);
    GetCommState(g_port, &dcb);
    dcb.BaudRate = baud;
    dcb.ByteSize = 8;
    dcb.Parity   = NOPARITY;
    dcb.StopBits = ONESTOPBIT;
    dcb.fBinary  = TRUE;
    dcb.fParity  = FALSE;
    dcb.fDtrControl = DTR_CONTROL_DISABLE;             // kmbox 一般不需要 DTR
    dcb.fRtsControl = RTS_CONTROL_DISABLE;
    SetCommState(g_port, &dcb);

    COMMTIMEOUTS to{};
    to.ReadIntervalTimeout        = MAXDWORD;          // 非阻塞读
    to.ReadTotalTimeoutConstant   = 0;
    to.WriteTotalTimeoutConstant  = 20;                // 写超时 20ms
    SetCommTimeouts(g_port, &to);

    PurgeComm(g_port, PURGE_RXCLEAR | PURGE_TXCLEAR);
    return true;
}

bool km_send(const std::string& cmd) {
    std::string line = cmd + "\r\n";
    DWORD written = 0;
    return WriteFile(g_port, line.data(), (DWORD)line.size(), &written, nullptr)
           && written == line.size();
}

