HANDLE hSerial = CreateFileA("\\\\.\\COM3",
    GENERIC_READ | GENERIC_WRITE, 0, NULL,
    OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);

DCB dcb = { sizeof(dcb) };
GetCommState(hSerial, &dcb);
dcb.BaudRate = 115200;
dcb.ByteSize = 8;
