// build: cl /EHsc /std:c++17 mem.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do {
            if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; }
        } while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

template <typename T>
bool RPM(HANDLE h, uintptr_t addr, T& out) {
    SIZE_T n = 0;
    return ReadProcessMemory(h, (LPCVOID)addr, &out, sizeof(T), &n) && n == sizeof(T);
}

int main() {
    DWORD pid = FindPid(L"[进程名].exe");
    if (!pid) { printf("pid not found\n"); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);

    uintptr_t base = GetModuleBase(pid, L"[模块名].exe");
    printf("game module base = 0x%llX\n", (unsigned long long)base);

    // 多级偏移链：base -> [base+0x[偏移1]] -> +0x[偏移2] -> +0x[偏移3]
    uintptr_t p1 = 0, p2 = 0, ent = 0;
    uintptr_t addr = base + 0x[偏移1];
    if (!RPM(h, addr, p1)) return 1;
    if (!RPM(h, p1 + 0x[偏移2], p2)) return 1;
    if (!RPM(h, p2 + 0x[偏移3], ent)) return 1;

    // 读实体列表头（UWorld / ULevel 依你的游戏引擎而定）
    int count = 0;
    if (!RPM(h, ent + 0x[偏移4], count)) return 1;
    uintptr_t list = 0;
    if (!RPM(h, ent + 0x[偏移5], list)) return 1;
    printf("entity count = %d, list = 0x%llX\n", count, (unsigned long long)list);

    CloseHandle(h);
    return 0;
}
```

偏移定位流程，逐条给你：

1. **模块基址**：`GetModuleBase` 已给，或 x64dbg 附加后看 `Modules` 窗口 `Base` 列。
2. **找锚点值**：CE 里先扫一个会变的值（HP / 金币 / 坐标）。坐标用 Float 扫描，金币用 4 字节。
3. **回溯指针**：CE → `Pointer scan`，最大层级 5，偏移上限 0x2000，得到候选链；每条链打开两个不同对局验证「基址变化后链是否仍指向同一语义」。
4. **结构体还原**：在 x64dbg 里对该地址下硬件断点（`bau` / `bpr`），看命中指令附近的 `mov`/`add` 偏移，把相邻字段一起拉出来（血量 - x 处通常是最大血量，坐标三连通常连续 0xC）。
5. **实体列表**：UE 系游戏从 `UWorld` → `PersistentLevel` → `Actors` 数组；Unity IL2CPP 从 `GObjects` 拉指针数组。这一步先 dump 头 0x20 个指针，找规律。
6. **验证**：改一个 HP 字段（先 dump 原值），看游戏内血条是否跟随。没跟随就是链错了，回到第 3 步。

