uint64_t resolve_chain(HANDLE h, uint64_t base, const uint64_t* off, int n) {
    uint64_t addr = base;
    for (int i = 0; i < n - 1; ++i) {
        ReadProcessMemory(h, (LPCVOID)(addr + off[i]), &addr, sizeof(addr), NULL);
        if (!addr) return 0;
