int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = (argc > 1) ? argv[1] : L"[进程名]";
    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"进程未找到: %s\n", proc); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess 失败: %lu\n", GetLastError()); return 1; }

    uintptr_t base = ModBase(pid, L"[模块名]");
    wprintf(L"PID=%lu  base=0x%llX\n", pid, (unsigned long long)base);

    // 血量的多级偏移链，从逆向里来；先占位，dynamic 角色扫出来后填真值
    // chain: [[base + 0x[偏移A]] + 0x[偏移B]] + 0x[偏移C]
    uintptr_t p1 = 0, p2 = 0, hpAddr = 0;
    SIZE_T rd = 0;
    if (!ReadProcessMemory(h, (LPCVOID)(base + 0x[偏移A]), &p1, sizeof(p1), &rd)) return 2;
    if (!ReadProcessMemory(h, (LPCVOID)(p1 + 0x[偏移B]), &p2, sizeof(p2), &rd)) return 3;
    hpAddr = p2 + 0x[偏移C];

    int hp = -1;
    ReadProcessMemory(h, (LPCVOID)hpAddr, &hp, sizeof(hp), &rd);
    wprintf(L"hpAddr=0x%llX  当前血量=%d\n", (unsigned long long)hpAddr, hp);

    // 改之前先 dump 原值，回滚用
    int orig = hp;
    wprintf(L"原值已记录: %d\n", orig);

    CloseHandle(h);
    return 0;
}
