// hp_probe.cpp —— MSVC x64：枚举 game.exe 模块基址 + 区域快照，为偏移扫描做准备
// cl /std:c++17 /O2 hp_probe.cpp /link Psapi.lib
#include <windows.h>
#include <psapi.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>

DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe))
        do { if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; } }
        while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

int wmain() {
    DWORD pid = FindPid(L"game.exe");            // 占位：[进程名]
    if (!pid) { wprintf(L"pid not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION
                           | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { wprintf(L"OpenProcess fail %lu\n", GetLastError()); return 1; }

    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        for (DWORD i = 0; i < need / sizeof(HMODULE); ++i) {
            wchar_t path[MAX_PATH]{};
            GetModuleFileNameExW(h, mods[i], path, MAX_PATH);
            MODULEINFO mi{};
            GetModuleInformation(h, mods[i], &mi, sizeof(mi));
            wprintf(L"[%016llX] size=%08X  %s\n",
                    (unsigned long long)mi.lpBaseOfDll, mi.SizeOfImage, path);
        }
    }

    // 区域枚举：拿到所有 committed / RW 区，供特征扫描与指针链回溯
    MEMORY_BASIC_INFORMATION mbi{};
    for (BYTE* p = 0; VirtualQueryEx(h, p, &mbi, sizeof(mbi)); p += mbi.RegionSize) {
        if (mbi.State == MEM_COMMIT &&
            (mbi.Protect & (PAGE_READWRITE | PAGE_WRITECOPY | PAGE_EXECUTE_READWRITE)))
            wprintf(L"RW  [%016llX - %016llX] %llu KB\n",
                    (unsigned long long)mbi.BaseAddress,
                    (unsigned long long)mbi.BaseAddress + mbi.RegionSize,
                    mbi.RegionSize / 1024);
    }
    CloseHandle(h);
    return 0;
}
```

血量定位的判定链（`dynamic` 必须按这个走，未验证的偏移一律标「未验证」）：

1. **CE 双值扫描锁候选**：已知血量上限（如 100）→ `First Scan: 100` → 掉血 → `Next Scan: <新值>` → 回血 → `Next Scan: 100`，通常收敛到 3~8 个地址；用 `Find out what writes this address` 拿到写入指令，此即血量写入点。
2. **区分本地缓存与服务端同步值**：对每个候选地址 `NOP` 写入或改值，看界面动没动 → 动了只是本地显示，还要看服务端回包是否覆盖回原值（回包覆盖说明血量权威在服务端，客户端只能做显示层）。
3. **回溯指针链**：找到写入点后，用 CE 的 `Pointer scan` 从静态基址（`game.exe+[偏移]`）回溯 2~4 级，落地成 `[[game.exe+0xXXXX]+0xNN]+0xNN` 形式，重启游戏验证稳定性。
4. **结构体还原**：以血量地址为中心向两侧读 ±0x100 字节，找相邻的已知数值（最大血量、护甲、蓝量、坐标）确定结构体字段布局与对齐。
5. **跨版本稳定性**：特征码扫描优先于硬编码偏移——取写入点附近 16~32 字节作为 AOB 特征，避开会变的立即数。

