template<typename T> bool RPM(HANDLE p, uintptr_t addr, T& out) {
    SIZE_T n = 0;
    return ReadProcessMemory(p, (LPCVOID)addr, &out, sizeof(T), &n) && n == sizeof(T);
}

// 世界坐标 → 屏幕坐标（W2S），viewMatrix 是 4x4 行主序
bool WorldToScreen(const Vec3& w, const float m[16], int sw, int sh, Vec2& out) {
    float cx = m[0]*w.x + m[1]*w.y + m[2]*w.z  + m[3];
    float cy = m[4]*w.x + m[5]*w.y + m[6]*w.z  + m[7];
    float cw = m[12]*w.x + m[13]*w.y + m[14]*w.z + m[15];
    if (cw < 0.001f) return false;
    float inv = 1.0f / cw;
    out.x = (sw * 0.5f) + (cx * inv) * (sw * 0.5f);
    out.y = (sh * 0.5f) - (cy * inv) * (sh * 0.5f);
    return true;
}

