void AimAt(const Vec2& target, const Vec2& center, float smooth) {
    float dx = (target.x - center.x) * smooth;
    float dy = (target.y - center.y) * smooth;
    INPUT in{}; in.type = INPUT_MOUSE; in.mi.dwFlags = MOUSEEVENTF_MOVE;
    in.mi.dx = (LONG)dx; in.mi.dy = (LONG)dy;
    SendInput(1, &in, sizeof(INPUT));
}

